import React, { useState } from "react";
import { updateTask, deleteTask, getTasks } from "../services/api";

function TaskItem({ task, setTasks, setError }) {
  const [editing, setEditing] = useState(false);
  const [formData, setFormData] = useState({
    title: task.title,
    description: task.description || "",
    location: task.location || "",
    scheduled_date: task.scheduled_date || "",
    weather_sensitive: task.weather_sensitive || false,
    status: task.status || "pending"
  });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({ ...formData, [name]: type === "checkbox" ? checked : value });
  };

  const handleUpdate = async () => {
    try {
      await updateTask(task.id, formData);
      setTasks(await getTasks()); // refresh list
      setEditing(false);
    } catch (err) {
      setError("Error updating task");
    }
  };

  const handleDelete = async () => {
    try {
      await deleteTask(task.id);
      setTasks(await getTasks()); // refresh list
    } catch (err) {
      setError("Error deleting task");
    }
  };

  return (
    <div className="task-item">
      {editing ? (
        <div>
          <input
            name="title"
            value={formData.title}
            onChange={handleChange}
          />
          <input
            name="description"
            value={formData.description}
            onChange={handleChange}
          />
          <input
            name="location"
            value={formData.location}
            onChange={handleChange}
          />
          <input
            type="date"
            name="scheduled_date"
            value={formData.scheduled_date || ""}
            onChange={handleChange}
          />
          <label>
            Weather Sensitive?
            <input
              type="checkbox"
              name="weather_sensitive"
              checked={formData.weather_sensitive}
              onChange={handleChange}
            />
          </label>
          <select
            name="status"
            value={formData.status}
            onChange={handleChange}
          >
            <option value="pending">Pending</option>
            <option value="in-progress">In Progress</option>
            <option value="done">Done</option>
          </select>
          <button onClick={handleUpdate}>Save</button>
          <button onClick={() => setEditing(false)}>Cancel</button>
        </div>
      ) : (
        <div>
          <strong>{task.title}</strong> — {task.description}
          <p>
            Location: {task.location || "N/A"} | Date:{" "}
            {task.scheduled_date || "N/A"} | Status: {task.status}
          </p>
          <button onClick={() => setEditing(true)}>Edit</button>
          <button onClick={handleDelete}>Delete</button>
        </div>
      )}
    </div>
  );
}

export default TaskItem;
